.index-form-field label {
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  color: var(--color-text-dark);
}

.index-form-field input,
.index-form-field select,
.index-form-field textarea {
  padding: var(--spacing-sm);
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background-color: var(--color-white);
  color: var(--color-text-dark);
  transition: var(--transition);
  min-height: 44px;
}

.index-form-field input:focus,
.index-form-field select:focus,
.index-form-field textarea:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(139, 111, 71, 0.1);
}

.index-booking-form button {
  width: 100%;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-hero h1 {
    font-size: 1.75rem;
  }

  .index-hero-tagline {
    font-size: 1rem;
  }

  .index-services {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-testimonials {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-testimonials-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .index-booking {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-booking-form {
    padding: var(--spacing-md);
  }

  .index-form-row {
    grid-template-columns: 1fr;
    gap: var(--spacing-sm);
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xl) 0;
  }

  .index-services {
    padding: var(--spacing-xl) 0;
  }

  .index-testimonials {
    padding: var(--spacing-xl) 0;
  }

  .index-booking {
    padding: var(--spacing-xl) 0;
  }

  .index-form-row {
    grid-template-columns: 1fr 1fr;
  }
}
